using UnityEngine;

public class Player : MonoBehaviour
{
    public float speed = 3f;

    void Start()
    {
        Debug.Log("시작 " + transform.position);
    }

    void Update()
    {
        float h = Input.GetAxisRaw("Horizontal");
        transform.position += new Vector3(h, 0, 0) * speed * Time.deltaTime;
        if (Time.frameCount == 60) Debug.Log("60프레임: " + transform.position.x.ToString("F2"));
    }
}

public class Spawner : MonoBehaviour
{
    int count = 0;

    void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space))
        {
            var go = new GameObject("총알" + (++count));
            go.AddComponent<Bullet>();
        }
        if (Time.frameCount == 5 || Time.frameCount == 30)
            Debug.Log("총알 수: " + Object.FindObjectsOfType<Bullet>().Length);
    }
}

